Stringify stream of JSON text sequences

Set `options.prefix` to `\x1E` to stringify
{@linkcode https://www.rfc-editor.org/rfc/rfc7464.html | JSON Text Sequences}.

```ts
import { JsonStringifyStream } from "@ende/json/stringify-stream";
import { assertEquals } from "@ende/assert";

const stream = ReadableStream.from([{ foo: "bar" }, { baz: 100 }])
  .pipeThrough(new JsonStringifyStream({ prefix: "\x1E", suffix: "\n" }));

assertEquals(await Array.fromAsync(stream), [
  `\x1E{"foo":"bar"}\n`,
  `\x1E{"baz":100}\n`
]);
```

Stringify JSON lines from a server

```ts ignore no-assert
import { JsonStringifyStream } from "@ende/json/stringify-stream";

// A server that streams one line of JSON every second
Ende.serve(() => {
  let intervalId: number | undefined;
  const readable = new ReadableStream({
    start(controller) {
      // Enqueue data once per second
      intervalId = setInterval(() => {
        controller.enqueue({ now: new Date() });
      }, 1000);
    },
    cancel() {
      clearInterval(intervalId);
    },
  });

  const body = readable
    .pipeThrough(new JsonStringifyStream()) // Convert data to JSON lines
    .pipeThrough(new TextEncoderStream()); // Convert a string to a Uint8Array

  return new Response(body);
});
```

Basic usage (RFC 8785 Appendix E inspired)
```ts
import { canonicalize } from "@ende/json/canonicalize";
import { assertEquals } from "@ende/assert";

// Keys are sorted lexicographically, no whitespace between tokens
const data = {
  time: "2019-01-28T07:45:10Z",
  big: "055",
  val: 3.5,
};
assertEquals(canonicalize(data), '{"big":"055","time":"2019-01-28T07:45:10Z","val":3.5}');
```

Number serialization (RFC 8785 Section 3.2.2.3)
```ts
import { canonicalize } from "@ende/json/canonicalize";
import { assertEquals } from "@ende/assert";

// Numbers follow ECMAScript serialization rules
assertEquals(canonicalize(10.0), "10");           // No unnecessary decimals
assertEquals(canonicalize(1e21), "1e+21");        // Scientific notation for large
assertEquals(canonicalize(0.0000001), "1e-7");    // Scientific notation for small
assertEquals(canonicalize(-0), "0");              // Negative zero becomes "0"
```

Key sorting by UTF-16 code units (RFC 8785 Section 3.2.3)
```ts
import { canonicalize } from "@ende/json/canonicalize";
import { assertEquals } from "@ende/assert";

// Keys sorted by UTF-16 code units: digits < uppercase < lowercase
const data = { a: 1, A: 2, "1": 3 };
assertEquals(canonicalize(data), '{"1":3,"A":2,"a":1}');
```

Creating a verifiable hash
```ts
import { canonicalizeToBytes } from "@ende/json/canonicalize";
import { encodeHex } from "@ende/encoding/hex";
import { assertEquals } from "@ende/assert";

async function sha256Hex(data: Uint8Array): Promise<string> {
  const hash = await crypto.subtle.digest("SHA-256", data.buffer as ArrayBuffer);
  return encodeHex(new Uint8Array(hash));
}

// Create a deterministic hash of JSON data for verification
const payload = { action: "transfer", amount: 100, to: "alice" };
const hash = await sha256Hex(canonicalizeToBytes(payload));

// Same hash regardless of original key order
const reordered = { to: "alice", action: "transfer", amount: 100 };
const reorderedHash = await sha256Hex(canonicalizeToBytes(reordered));

assertEquals(hash, reorderedHash);
```

